  function taxonomyView(row){const t=taxonomyOf(row);return `<section class="cpr-product-taxonomy" aria-label="商品品类建议">${t.status==='suggestion'?`<span class="cpr-taxonomy-label">品类建议 · 待核对</span>${facts([['一级',t.level1],['二级',t.level2],['三级',t.level3]])}${t.matched_text||t.evidence_text?`<details><summary>分类依据</summary><p class="cpr-source-text">${e([t.matched_text,t.evidence_text].filter(Boolean).join('\n'))}</p></details>`:''}`:note('尚未分类 · 待核对。缺少明确品类依据时，不自动归为非照明。')}<small>用于整理研究样本，不代表已确认规格、品牌归属或产品适配。</small></section>`;}
