  function opportunityEligibility(item,run){const reasons=[],remote=item?.opportunity_eligibility;if(remote?.eligible===false)reasons.push(...list(remote.reasons).filter(v=>typeof v==='string'));const ids=[...new Set(list(item?.record_ids))],records=list(run?.records);if(!ids.length)reasons.push('建议没有关联可核对的商品记录。');for(const id of ids){const record=records.find(row=>row.id===id);if(!record){reasons.push('建议引用的商品记录不在本次任务中。');continue;}const value=recordValues(record),guard=record.opportunity_eligibility,context=value.market_context||{};if(guard?.eligible===false)reasons.push(...(list(guard.reasons).filter(v=>typeof v==='string').length?list(guard.reasons).filter(v=>typeof v==='string'):['该商品尚未通过市场与品牌资格核对。']));if(context.status==='mismatch')reasons.push('商品配送或站点市场与研究国家冲突。');else if(guard?.eligible!==true&&!(context.status==='sample_context_confirmed'&&context.country_confirmed===true&&context.sales_country&&context.sales_country===context.research_country))reasons.push('缺少本次采样已确认的销售国家依据。');if(!String(value.brand||'').trim())reasons.push('缺少主商品品牌，不能认定属于目标客户或品牌。');else if(guard?.eligible!==true&&value.brand_scope_validation?.matched!==true)reasons.push('主商品品牌尚未通过明确品牌范围核对。');}if(remote?.eligible===false&&!reasons.length)reasons.push('当前市场或品牌依据不足，不能作为有效产品机会。');return {eligible:reasons.length===0,reasons:[...new Set(reasons)]};}
