    const accepted=list(run.accepted_ids||run.accepted_record_ids),ready=shown.filter(r=>!accepted.includes(r.id)&&!r.accepted&&recordValues(r).market_context?.status!=='mismatch'),selected=ready.filter(r=>S.recordSelection.has(r.id));
